/*
 * A008907  Number of legal tic-tac-toe (or noughts and crosses) positions
 *          after n plays, up to rotation and reflection.
 * https://oeis.org/A008907
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   a(n) = number of legal Tic‑Tac‑Toe positions after n plays, up
 *            to rotation and reflection. The values are generated by
 *            exhaustive enumeration of all reachable boards
 * Range:     u8 n <= 9, u16 n <= 9, u32 n <= 9, u64 n <= 9, u128 n <= 9,
 *            big any n
 * Helpers:   decode_board, encode_board_from_cells, has_won
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/decode_board.h"
#include "../utils/encode_board_from_cells.h"
#include "../utils/has_won.h"

#define HASH_SIZE (1 << 20)    /* 1,048,576 entries, > 4× number of states */

/* Forward declarations of the requested function signature */
seq_t a(idx_t n);

/* ---------- Helper types -------------------------------------------- */
typedef struct {
    uint32_t board;   /* 2 bits per field for 9 cells: 0 empty, 1 X, 2 O */
    int plays;        /* number of plays made (i.e., filled cells) */
} Node;

/* ---------- Canonical transformation data --------------------------- */
static int perms[8][9];   /* 8 symmetry transforms: index 0..7 */

/* Precompute the 8 symmetry transforms: rotations (0,90,180,270) and
   each followed by a vertical reflection if flag is set. */
static void init_perms(void)
{
    for (int r = 0; r < 4; ++r) {
        for (int f = 0; f < 2; ++f) {
            int t = r * 2 + f;
            for (int src = 0; src < 9; ++src) {
                int row = src / 3;
                int col = src % 3;
                /* Reflection across vertical axis */
                if (f) col = 2 - col;
                /* Rotation r times (90° clockwise each time) */
                for (int k = 0; k < r; ++k) {
                    int tmp = row;
                    row = col;
                    col = 2 - tmp;
                }
                int dest = row * 3 + col;
                perms[t][dest] = src;
            }
        }
    }
}

/* Compute minimal canonical representation of a board */
static uint32_t canonical(uint32_t board)
{
    uint8_t cells[9];
    decode_board(board, cells);
    uint32_t best = 0xFFFFFFFFu;
    for (int t = 0; t < 8; ++t) {
        uint32_t b = 0;
        for (int dest = 0; dest < 9; ++dest) {
            uint8_t val = cells[perms[t][dest]];
            b |= (uint32_t)val << (2 * dest);
        }
        if (b < best) best = b;
    }
    return best;
}

/* ---------- Hash table for canonical boards ------------------------ */
static uint32_t hash_table[HASH_SIZE];

static bool hash_insert(uint32_t key)
{
    uint32_t h = key & (HASH_SIZE - 1);
    while (hash_table[h] != 0xFFFFFFFFu) {
        if (hash_table[h] == key) return false;  /* already present */
        h = (h + 1) & (HASH_SIZE - 1);
    }
    hash_table[h] = key;
    return true;
}

/* ---------- Main sequence computation ------------------------------ */
static seq_t counts[10] = {0};
static bool initialized = false;

seq_t a(idx_t n)
{
    if (n > 9) return 0;   /* after 9 plays no more positions are possible */

    if (!initialized) {
        /* Initialize permutations and hash table */
        init_perms();
        for (size_t i = 0; i < HASH_SIZE; ++i) hash_table[i] = 0xFFFFFFFFu;

        /* Stack for DFS */
        static Node stack[300000];
        size_t sp = 0;
        stack[sp++] = (Node){0u, 0};   /* empty board */

        while (sp) {
            Node node = stack[--sp];
            uint32_t canon = canonical(node.board);
            if (!hash_insert(canon)) continue;   /* already processed */

            /* Increment count for this canonical position */
            counts[node.plays]++;

            /* Decode to test for win and to count X/O for next player */
            uint8_t cells[9];
            decode_board(node.board, cells);
            if (has_won(cells) || node.plays == 9) continue;

            int xcnt = 0, ocnt = 0;
            for (int i = 0; i < 9; ++i) {
                if (cells[i] == 1) ++xcnt;
                else if (cells[i] == 2) ++ocnt;
            }
            int next = (xcnt == ocnt) ? 1 : 2;   /* X starts first */

            /* Generate children */
            for (int i = 0; i < 9; ++i) {
                if (cells[i] == 0) {
                    uint32_t shift = 2 * i;
                    uint32_t new_board = (node.board & ~(3u << shift)) | ((uint32_t)next << shift);
                    stack[sp++] = (Node){new_board, node.plays + 1};
                }
            }
        }
        initialized = true;
    }
    return counts[(int)n];
}
